using System;using System.IO;using System.Linq;using System.Drawing;using System.Drawing.Drawing2D;using System.Drawing.Imaging;using System.Threading;using System.Threading.Tasks;using System.Windows.Forms;using System.Diagnostics;
namespace AgitCon {
    internal static class ConfirmationVisionTests {
        static Bitmap Fixture(float scale,bool dark,string mark,string label=ConfirmationVision.Label){var image=new Bitmap((int)(560*scale),(int)(190*scale),PixelFormat.Format32bppArgb);using(var g=Graphics.FromImage(image)){g.SmoothingMode=SmoothingMode.AntiAlias;g.ScaleTransform(scale,scale);g.Clear(dark?Color.FromArgb(34,37,40):Color.FromArgb(250,250,250));using(var font=new Font("맑은 고딕",14,FontStyle.Regular,GraphicsUnit.Pixel))using(var brush=new SolidBrush(dark?Color.WhiteSmoke:Color.FromArgb(36,36,36)))g.DrawString(label,font,brush,70,80);Color fill=mark=="blue"?Color.DodgerBlue:Color.FromArgb(255,221,0);if(mark!="off"&&mark!="missing"){using(var brush=new SolidBrush(fill))g.FillEllipse(brush,35,80,20,20);using(var pen=new Pen(Color.FromArgb(30,30,30),1.7f)){if(mark=="on"||mark=="blue")g.DrawLines(pen,new[]{new PointF(40,89.17f),new PointF(43.33f,92.5f),new PointF(49.17f,85.83f)});if(mark=="cross"){g.DrawLine(pen,40,85,50,95);g.DrawLine(pen,50,85,40,95);}if(mark=="dot")g.FillEllipse(Brushes.Black,43,88,4,4);if(mark=="short")g.DrawLine(pen,40,89,44,93);}}else if(mark=="off")using(var pen=new Pen(Color.FromArgb(170,170,170),1))g.DrawEllipse(pen,35,80,20,20);}return image;}
        internal static void Run(){string report=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"confirmation-vision-test.txt");try{Task.Run(async()=>{int checks=0,on=0,off=0,unknown=0;foreach(bool dark in new[]{false,true})foreach(float scale in new[]{1f,1.25f,1.5f,1.75f,2f,2.25f,2.5f,3f,3.5f,4f})foreach(string mark in new[]{"on","off","missing","dot","cross","short","blue"})using(var image=Fixture(scale,dark,mark)){int state=await ConfirmationVision.Read(image,CancellationToken.None);checks++;if(state==1)on++;else if(state==-1)off++;else unknown++;if(mark!="on"&&state==1)throw new Exception("False ON: "+mark+" dark="+dark+" scale="+scale);if(mark=="on"&&!dark&&state!=1)throw new Exception("Known light ON missed at scale="+scale);int glyph=ConfirmationVision.Marker(image,new RectangleF(70*scale,83*scale,240*scale,15*scale));checks++;if(mark=="on"&&glyph!=1)throw new Exception("ON glyph missed "+scale);if(mark!="on"&&glyph==1)throw new Exception("False ON glyph: "+mark);}
            foreach(string label in new[]{"파일 전송", "사진 전송 시 묶어 보내기", ""})using(var image=Fixture(1,false,"on",label)){if(await ConfirmationVision.Read(image,CancellationToken.None)==1)throw new Exception("Wrong label accepted");checks++;}
            using(var image=Fixture(1,false,"on")){using(var g=Graphics.FromImage(image))using(var f=new Font("맑은 고딕",14,FontStyle.Regular,GraphicsUnit.Pixel))g.DrawString(ConfirmationVision.Label,f,Brushes.Black,70,125);if(await ConfirmationVision.Read(image,CancellationToken.None)==1)throw new Exception("Duplicate label accepted");checks++;}
            foreach(float scale in new[]{1f,1.25f,1.5f,1.75f,2f,2.25f,2.5f,3f,3.5f,4f})using(var image=Fixture(scale,false,"on"))using(var cut=image.Clone(new Rectangle((int)(55*scale),0,image.Width-(int)(55*scale),image.Height),PixelFormat.Format32bppArgb)){if(await ConfirmationVision.Read(cut,CancellationToken.None)==1)throw new Exception("Clipped marker accepted");checks++;}
            foreach(bool dark in new[]{false,true})foreach(float scale in new[]{1f,1.25f,1.5f,1.75f,2f,2.25f,2.5f,3f,3.5f,4f})using(var stream=typeof(ConfirmationVision).Assembly.GetManifestResourceStream("AgitCon.KakaoSettingsGear.png"))using(var gear=new Bitmap(stream))using(var strip=new Bitmap((int)(66*scale),(int)(707*scale),PixelFormat.Format32bppArgb)){if(dark)for(int y=0;y<gear.Height;y++)for(int x=0;x<gear.Width;x++){var c=gear.GetPixel(x,y);gear.SetPixel(x,y,Color.FromArgb(c.A,255-c.R,255-c.G,255-c.B));}using(var g=Graphics.FromImage(strip)){g.Clear(dark?Color.FromArgb(20,20,20):Color.FromArgb(238,238,238));g.DrawImage(gear,new Rectangle((int)(20*scale),(int)(557*scale),(int)(24*scale),(int)(24*scale)));}var point=ConfirmationVision.Gear(strip,scale);if(!point.HasValue||Math.Abs(point.Value.X-32*scale)>3||Math.Abs(point.Value.Y-569*scale)>3)throw new Exception("Gear missed "+scale+" dark="+dark);checks++;using(var g=Graphics.FromImage(strip))g.Clear(Color.White);if(ConfirmationVision.Gear(strip,scale).HasValue)throw new Exception("Blank gear accepted");checks++;}
            File.WriteAllText(report,"PASS: "+checks+" synthetic image/OCR cases; ON="+on+", OFF="+off+", UNKNOWN="+unknown+"; false ON=0; unsupported OCR states stay UNKNOWN. Light/dark fixtures at 100/125/150/175/200/225/250/300/350/400%, missing/dot/cross/short/wrong-color/label/duplicate/clipped controls. Actual Windows DPI/theme settings were not changed. No Kakao or clipboard/input interaction.\r\n");}).GetAwaiter().GetResult();}catch(Exception ex){File.WriteAllText(report,"FAIL: "+ex);Environment.ExitCode=1;}}
        internal static void GearReadiness(){string report=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"gear-readiness-test.txt");int checks=0;Action<bool> check=value=>{if(!value)throw new Exception("Gear readiness check "+checks);checks++;};try{Task.Run(async()=>{
            foreach(float scale in new[]{1f,1.5f,2f,3f,4f}){
                Func<int,Bitmap> frame=shift=>{var image=new Bitmap((int)(66*scale),(int)(400*scale),PixelFormat.Format32bppArgb);using(var graphics=Graphics.FromImage(image)){graphics.Clear(Color.FromArgb(238,238,238));if(shift>=0)using(var stream=typeof(ConfirmationVision).Assembly.GetManifestResourceStream("AgitCon.KakaoSettingsGear.png"))using(var gear=new Bitmap(stream))graphics.DrawImage(gear,new Rectangle((int)(20*scale),(int)(300*scale)+shift,(int)(24*scale),(int)(24*scale)));}return image;};
                int captures=0;var settled=await ConfirmationNavigator.StableGear(()=>frame(++captures==1?-1:0),scale,()=>true,CancellationToken.None,1);check(settled.Point.HasValue&&captures==3);
                captures=0;var blank=await ConfirmationNavigator.StableGear(()=>{captures++;return frame(-1);},scale,()=>true,CancellationToken.None,1);check(!blank.Point.HasValue&&captures==4&&blank.Detail.Contains("match=False"));
                captures=0;var unstable=await ConfirmationNavigator.StableGear(()=>frame(++captures%2==0?0:40),scale,()=>true,CancellationToken.None,1);check(!unstable.Point.HasValue&&captures==4);
                captures=0;var lost=await ConfirmationNavigator.StableGear(()=>{captures++;return frame(0);},scale,()=>captures==0,CancellationToken.None,1);check(!lost.Point.HasValue&&captures==1&&lost.Detail=="focus-changed");
                using(var cancel=new CancellationTokenSource()){cancel.Cancel();bool canceled=false;try{await ConfirmationNavigator.StableGear(()=>frame(0),scale,()=>true,cancel.Token,1);}catch(OperationCanceledException){canceled=true;}check(canceled);}
            }
        }).GetAwaiter().GetResult();File.WriteAllText(report,"PASS: "+checks+" synthetic readiness cases at 100/150/200/300/400%; blank first frame then two stable gears, blank/unstable frames blocked, focus loss and cancellation. No real windows, restoration, clicks, Kakao or clipboard. Actual minimized Kakao restoration remains unverified.");}catch(Exception ex){File.WriteAllText(report,"FAIL: "+ex);Environment.ExitCode=1;}}
        internal static void NavigationProbe(){Application.EnableVisualStyles();using(var monitor=new PreviewPaste())using(var form=new Form{Text="아지트콘 · 설정 확인 시험",Width=400,Height=190,StartPosition=FormStartPosition.CenterScreen})using(var timer=new System.Windows.Forms.Timer{Interval=100}){monitor.ConfigurePersistentGif(true,0,0,null);var button=new Button{Text="설정만 확인 (첨부 없음)",Dock=DockStyle.Top,Height=45};var label=new Label{Text="카톡 입력란을 한 번 누른 뒤 이 버튼을 골라주세요.",Dock=DockStyle.Fill};form.Controls.Add(label);form.Controls.Add(button);timer.Tick+=(s,e)=>{if(!monitor.FileAttachmentInProgress)monitor.Observe();};timer.Start();button.Click+=async(s,e)=>{button.Enabled=false;try{using(var cts=new CancellationTokenSource(12000)){var result=await monitor.TryPhotoAttach(monitor.Snapshot(),cts.Token,Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"diagnostics","sample.gif"),form.Handle,true);label.Text=result.Stage+"; "+result.Block+"; "+result.Reason;File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"confirmation-navigation-probe.txt"),label.Text+"\r\nProduction PreviewPaste focus hooks; verificationOnly stops before Ctrl+T, file selection or Open. No clipboard/Send.\r\n");}}catch(Exception ex){label.Text=ex.GetType().Name;}finally{button.Enabled=true;}};Application.Run(form);}}
        internal static void LiveRead(){string report=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"confirmation-vision-live.txt");try{var processes=Process.GetProcessesByName("KakaoTalk");try{if(processes.Length!=1)throw new Exception("Ambiguous process");uint process=(uint)processes[0].Id;var reading=Task.Run(()=>ConfirmationNavigator.ReadVisible(process,ConfirmationNavigator.FindMain(process),CancellationToken.None)).GetAwaiter().GetResult();File.WriteAllText(report,"State="+reading.State+"; stage="+reading.Stage+"\r\nOnly currently visible settings; no input, clipboard, files attached or sent.\r\n");}finally{foreach(var process in processes)process.Dispose();}}catch(Exception ex){File.WriteAllText(report,"ERROR: "+ex.GetType().Name);Environment.ExitCode=1;}}
    }
}
